from collections import namedtuple, defaultdict
from contextlib import contextmanager
from taf.ul.ettf.logger import custom_logger
from taf.ul.ettf.events.comparator import Comparator
from taf.ul.ettf.events.lifetime_policy import Forever, LifetimePolicy
from taf.ul.ettf.events.registration_condition import RegistrationCondition, Always
from taf.ul.ettf.events.move_policy import MovePolicy, Forbidden
from taf.ul.ettf.utils.exception import LibraryError
from taf.ul.ettf.utils.singleton import Singleton


logger = custom_logger('Notifier')
Queued = namedtuple('Queued', ['comparator', 'callback', 'lifetime_policy'])
Group = namedtuple('Group', ['name', 'move_policy'])


class NotifierHistory(defaultdict):
    def get(self, key):
        return self[key]


class NotifierError(LibraryError):
    pass


def allow_one_per_notifier_group(func):
    def wrap(*args, **kwargs):
        map = Notifier().history.get(Notifier().active_group_name)
        if func not in map:
            return_value = func(*args, **kwargs)
            map.append(func)
            return return_value
    return wrap


class Notifier(Singleton):
    callbacks = defaultdict(list)
    groups = [Group('default', Forbidden())]
    _active_event = None
    history = NotifierHistory(list)

    def register(self, callback, comparator, lifetime_policy=Forever(), registration_condition=Always()):
        self._verify_registration_correctness(callback, comparator, lifetime_policy, registration_condition)
        self._append(Queued(comparator, callback, lifetime_policy), registration_condition)
        logger.debug('Callback registered. Callback: {}, comparator: {}'.format(callback, comparator))

    def notify(self, event, decorator=None):
        logger.debug('Event notification. Event: {}'.format(event))

        with self._storeEvent(event):
            for callback_data in self._provide_callbacks_data(event):
                logger.debug('Calling callback: {}'.format(callback_data.callback))

                if callback_data.lifetime_policy.should_be_called():
                    callback_data.callback() if not decorator else decorator(callback_data.callback)
                callback_data.lifetime_policy.callback_called()

                if callback_data.lifetime_policy.should_be_removed():
                    self._remove_data(callback_data)

    @property
    def active_event(self):
        return self._active_event

    @property
    def active_group_name(self):
        return self.groups[-1].name

    def open_group(self, name, move_policy=Forbidden()):
        self._verify_opening_group_correctness(move_policy)

        if self._group_exists(name):
            raise NotifierError('Group names should be unique. Group {} already exists.'.format(name),
                                'Group {}'.format(name))

        self.groups.append(Group(name, move_policy))
        logger.debug('Added new group with name {}'.format(name))

    def close_active_group(self):
        if len(self.groups) > 1:
            self.history[self.active_group_name] = []
            group = self.groups.pop()
            logger.debug('Group {} is closed'.format(group.name))
            group.move_policy.move(self.callbacks[group.name], self.callbacks[self.active_group_name])
        else:
            logger.debug('Only one group left. {} group cannot be closed'.format(self.active_group_name))
            pass

    def clear(self):
        self.history = NotifierHistory(list)
        self.callbacks.clear()
        self.groups = [Group('default', Forbidden())]
        self._active_event = None
        logger.debug('Notification queue and history cleared')

    def has_callbacks(self):
        return bool(self.callbacks.keys())

    @contextmanager
    def _storeEvent(self, event):
        try:
            self._active_event = event
            yield
        finally:
            self._active_event = None

    def _group_exists(self, name):
        return name in [g.name for g in self.groups]

    def _append(self, callback_data, registration_condition):
        if registration_condition(callback_data.callback, [data.callback for data in self._active_callbacks()]):
            self.callbacks[self.active_group_name].append(callback_data)

    def _active_callbacks(self):
        return self.callbacks[self.active_group_name]

    def _remove_data(self, data):
        self._active_callbacks().remove(data)

    def _verify_registration_correctness(self, callback, comparator, lifetime_policy, registration_condition):
        if not callable(callback):
            raise NotifierError('Callback should be callable.',
                                'Callback: {}'.format(callback))
        if not isinstance(comparator, Comparator):
            raise NotifierError('Comparator should inherit from Comparator class.',
                                'Comparator: {}'.format(comparator))
        if not isinstance(lifetime_policy, LifetimePolicy):
            raise NotifierError('Lifetime policy should inherit from LifetimePolicy class.',
                                'Policy: {}'.format(lifetime_policy))
        if not isinstance(registration_condition, RegistrationCondition):
            raise NotifierError('Registration condition should inherit from RegistrationCondition class.',
                                'Condition: {}'.format(registration_condition))

    def _verify_opening_group_correctness(self, move_policy):
        if not isinstance(move_policy, MovePolicy):
            raise NotifierError('Move policy should inherit from MovePolicy class.',
                                'Policy: {}'.format(move_policy))

    def _provide_callbacks_data(self, event):
        return [queued for queued in self._active_callbacks() if queued.comparator(event)]
